<template><label class="vs-radio"><input :checked="modelValue===value" type="radio" :name="name" :value="value" :disabled="disabled" @change="$emit('update:modelValue', value)" /><span aria-hidden="true"></span><strong>{{ label }}</strong></label></template>
<script setup>defineProps({modelValue:{type:[String,Number,Boolean],default:''},value:{type:[String,Number,Boolean],required:true},name:{type:String,required:true},label:{type:String,required:true},disabled:Boolean});defineEmits(['update:modelValue'])</script>
<style scoped>.vs-radio{display:inline-flex;align-items:center;gap:var(--space-2);min-height:44px;cursor:pointer}.vs-radio input{position:absolute;opacity:0}.vs-radio span{width:22px;height:22px;border:1px solid var(--border-strong);border-radius:50%;background:var(--surface-default)}.vs-radio input:checked+span{border:6px solid var(--interactive-primary)}.vs-radio input:focus-visible+span{outline:3px solid color-mix(in srgb,var(--border-focus) 35%,transparent);outline-offset:2px}.vs-radio strong{font-size:var(--type-body-size)}</style>
